import os
import boto3
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential

def get_azure_document_intelligence_client(config: dict):
    endpoint = config.get('AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT') or os.environ.get('AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT')
    api_key = config.get('AZURE_DOCUMENT_INTELLIGENCE_API_KEY') or os.environ.get('AZURE_DOCUMENT_INTELLIGENCE_API_KEY')
    if not endpoint or not api_key:
        raise ValueError("Azure Document Intelligence endpoint and API key must be provided.")
    return DocumentIntelligenceClient(endpoint, AzureKeyCredential(api_key))

def get_aws_textract_client(config: dict):
    aws_access_key_id = config.get('AWS_ACCESS_KEY_ID') or os.environ.get('AWS_ACCESS_KEY_ID')
    aws_secret_access_key = config.get('AWS_SECRET_ACCESS_KEY') or os.environ.get('AWS_SECRET_ACCESS_KEY')
    aws_region_name = config.get('AWS_REGION_NAME') or os.environ.get('AWS_REGION_NAME') or 'us-east-1'

    if not aws_access_key_id or not aws_secret_access_key:
        raise ValueError("AWS access key ID and secret access key must be provided.")

    return boto3.client(
        'textract',
        aws_access_key_id=aws_access_key_id,
        aws_secret_access_key=aws_secret_access_key,
        region_name=aws_region_name
    )

from document_models import NormalizedExpense
from typing import Dict, Any

def validate_document_fields(normalized_expense: NormalizedExpense) -> Dict[str, Any]:
    validation_results = {
        "is_valid": True,
        "missing_fields": [],
        "validation_errors": []
    }

    # Example of required fields. This can be extended based on business rules.
    required_fields = [
        "total_amount",
        "transaction_date",
    ]

    if not normalized_expense.vendor_name and not normalized_expense.merchant_name:
        validation_results["missing_fields"].append("vendor_name or merchant_name")
        validation_results["is_valid"] = False

    for field in required_fields:
        if getattr(normalized_expense, field) is None:
            validation_results["missing_fields"].append(field)
            validation_results["is_valid"] = False

    # Basic numerical validation for total_amount and tax_amount if they exist
    if normalized_expense.total_amount:
        try:
            float(normalized_expense.total_amount)
        except ValueError:
            validation_results["validation_errors"].append("total_amount is not a valid number")
            validation_results["is_valid"] = False

    if normalized_expense.tax_amount:
        try:
            float(normalized_expense.tax_amount)
        except ValueError:
            validation_results["validation_errors"].append("tax_amount is not a valid number")
            validation_results["is_valid"] = False

    # In a real scenario, confidence scores from the original extraction would be passed through
    # and validated here as well.

    return validation_results

import os
from typing import Dict, Any
from pymongo import MongoClient
from pymongo.errors import ConnectionFailure
from document_models import NormalizedExpense

def persist_expense_record(expense_record: NormalizedExpense, config: Dict[str, Any] = None) -> Dict[str, Any]:
    config = config or {}

    # MongoDB Atlas connection string from environment or config
    mongodb_uri = config.get('MONGODB_URI') or os.environ.get('MONGODB_URI')
    if not mongodb_uri:
        raise ValueError("MONGODB_URI must be provided to connect to MongoDB Atlas.")

    database_name = config.get('MONGODB_DATABASE') or os.environ.get('MONGODB_DATABASE') or "expense_db"
    collection_name = config.get('MONGODB_COLLECTION') or os.environ.get('MONGODB_COLLECTION') or "expense_records"

    try:
        client = MongoClient(mongodb_uri)
        # The ping command is cheap and does not require auth.
        client.admin.command('ping')
        db = client[database_name]
        collection = db[collection_name]

        # Convert Pydantic model to dictionary for MongoDB insertion
        record_dict = expense_record.dict(by_alias=True)

        result = collection.insert_one(record_dict)
        return {"status": "success", "inserted_id": str(result.inserted_id)}
    except ConnectionFailure as e:
        print(f"MongoDB connection failed: {e}")
        return {"status": "error", "message": f"MongoDB connection error: {e}"}
    except Exception as e:
        print(f"An error occurred while persisting expense record: {e}")
        return {"status": "error", "message": f"Failed to persist record: {e}"}
    finally:
        if 'client' in locals() and client:
            client.close()
